function gearPage(){const r=by("components",sel.components)||{},moor=r.mooringId||sel.moorings||"",componentOptions=rows("components").filter(x=>!moor||x.mooringId===moor);return '<div class="actions">'+btn("new","New component","components")+"</div>"+listing("components",[["Component",x=>esc(x.label)],["Mooring",x=>esc(label("moorings",x.mooringId))],["Physical state",x=>badge(x.state)],["Storage",x=>esc(x.storage)]])+form("save-components",r.id?"Component identity":"Enter an actual component",hidden(r)+pick("mooringId","Original mooring",rows("moorings"),r.mooringId,false,!!r.id)+input("label","Component label",r.label,"text","",true)+input("kind","Component kind",r.kind)+area("description","Original component description",r.description)+input("serial","Serial / tag reference",r.serial)+input("installedAt","Known original install date",r.installedAt,"date")+area("notes","Notes",r.notes))+(r.id?hist("components",r.id):"")+form("gear-move","Record a physical gear move",pick("mooringId","Mooring",rows("moorings"),moor)+pick("componentIds","Actual components",componentOptions,[],true)+pick("state","Actual destination state",["installed","winter","stored","retired"],"")+input("location","Actual destination / storage location","","text","",true)+input("at","Moved at","","text","ISO date-time with offset.",true)+pick("jobId","Related job",rows("jobs"),"")+area("reason","Work and movement reason"),"Record movement")+'<section class="panel"><h2>Original field evidence</h2><p>Select the complete original file, then explicitly attach it to its mooring/job. No network upload occurs.</p><label>Evidence file<input id="evidence-file" type="file"></label><p id="evidence-summary">'+esc(evidenceFile?evidenceFile.name+" · "+evidenceFile.bytes+" bytes":"No original file selected.")+"</p></section>"+form("evidence-add","Attach original evidence",pick("mooringId","Mooring",rows("moorings"),moor)+pick("jobId","Related job",rows("jobs"),"")+area("notes","Evidence notes"),"Attach exact original",!evidenceFile)+table(["Evidence","Mooring","Bytes","Open / download"],rows("evidence").map(x=>[esc(x.name),esc(label("moorings",x.mooringId)),esc(x.bytes),btn("evidence-download","Download original",x.id)]))+details("Physical movement history",rows("movements"));}
